                    invest_amount = 0.40 * portfolio_value
                    shares = math.floor(invest_amount / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)

            # Update previous values for next bar's cross detection
            self.prev_spy_close = spy_close
            self.prev_spy_sma = spy_sma_val

