from AlgorithmImports import *

class DualStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in tickers:
            eq = self.AddEquity(t, Resolution.Daily)
            eq.SetDataNormalizationMode(DataNormalizationMode.Raw)
            self.symbols[t] = eq.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # NOTE: The SMA period for Strategy A was not specified in the prompt.
        # A 50-day simple moving average is used as a standard trend-following default.
        self.sma_period = 50
        self.smaSPY = self.SMA(self.spy, self.sma_period, Resolution.Daily)
        self.rsiAAPL = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Previous-day cached values for cross detection
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # AAPL red-day streak tracking (market-state, always computed)
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(self.sma_period, Resolution.Daily)

    def OnData(self, data: Slice):
        # Skip entire day's rule evaluation if any subscribed ticker's bar is missing
        for sym in self.symbols.values():
            if not data.ContainsKey(sym) or data[sym] is None:
                return

        spy_close = data[self.spy].Close
        aapl_close = data[self.aapl].Close

        # ---- Update AAPL red-day streak (continuous, not gated) ----
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        ready = (self.smaSPY.IsReady and self.rsiAAPL.IsReady and not self.IsWarmingUp)
        prev_ready = (self.prev_spy_close is not None and self.prev_spy_sma is not None)

        if ready and prev_ready:
            current_sma = self.smaSPY.Current.Value

            # ---- Slot 1: Strategy A (SPY) ----
            lotA_qty = self.Portfolio[self.spy].Quantity

            crossed_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > current_sma)
            crossed_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < current_sma)

            # Sells before buys
            if lotA_qty > 0:
                if crossed_below:
                    self.Liquidate(self.spy)
            else:
                if crossed_above:
                    target_value = 0.4 * self.Portfolio.TotalPortfolioValue
                    shares = int(target_value // spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)

            # ---- Slot 2: Strategy B (AAPL) ----
            lotB_qty = self.Portfolio[self.aapl].Quantity

            if lotB_qty > 0:
                if self.rsiAAPL.Current.Value > 60:
                    self.Liquidate(self.aapl)
            else:
                if self.aapl_red_streak >= 3:
                    cash = self.Portfolio.Cash
                    if cash >= 20000:
                        shares = int(20000 // aapl_close)
                        if shares > 0:
                            self.MarketOrder(self.aapl, shares)

        # ---- Cache today's values as "previous" for next bar's cross checks ----
        self.prev_spy_close = spy_close
        self.prev_spy_sma = self.smaSPY.Current.Value if self.smaSPY.IsReady else None
        self.prev_aapl_close = aapl_close

